var ACTIVE_FOLLOWUP_TAB = 'ALL';
var NOTIFIED_FOLLOWUP_IDS = new Set();
var FOLLOWUP_TICKER_INTERVAL = null;

function isFollowupOverdue(fu) {
  if (!fu || fu.status !== 'PENDING') return false;
  if (!fu.date) return false;
  try {
    const [y, m, d] = fu.date.split('-').map(Number);
    if (!y || !m || !d) return false;

    let hours = 11;
    let minutes = 0;
    const timeStr = fu.time || '11:00 AM';
    const match = timeStr.match(/(\d+):(\d+)\s*(AM|PM)/i);
    if (match) {
      hours = parseInt(match[1], 10);
      minutes = parseInt(match[2], 10);
      const ampm = match[3].toUpperCase();
      if (ampm === 'PM' && hours < 12) hours += 12;
      if (ampm === 'AM' && hours === 12) hours = 0;
    }

    const scheduled = new Date(y, m - 1, d, hours, minutes);
    return scheduled < new Date();
  } catch (e) {
    return false;
  }
}

function getFollowupDueStatus(fu) {
  if (!fu) return 'PENDING';
  if (fu.status === 'COMPLETED') {
    return fu.outcome === 'LOST' ? 'LOST' : 'COMPLETED';
  }
  if (isFollowupOverdue(fu)) return 'OVERDUE';
  const today = new Date().toISOString().split('T')[0];
  if (fu.date === today) return 'TODAY';
  if (fu.date > today) return 'UPCOMING';
  return 'OVERDUE';
}


function openEditFollowupModal(fuId) {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('followups', 'edit')) {
    if (typeof showToast === 'function') {
      showToast('Permission Denied', 'Your assigned role does not have permission to edit follow-ups.', 'lock', 'rose');
    }
    return;
  }
  const fu = (CRM_STATE.followups || []).find(f => f && f.id === fuId);
  if (!fu) {
    if (typeof showToast === 'function') showToast('Error', 'Follow-up not found.', 'error', 'rose');
    return;
  }

  const editIdInput = document.getElementById('followup-edit-id');
  if (editIdInput) editIdInput.value = fu.id;

  const titleEl = document.getElementById('modal-followup-title');
  if (titleEl) titleEl.innerText = 'Edit Customer Follow-up';
  const descEl = document.getElementById('modal-followup-desc');
  if (descEl) descEl.innerText = 'Update callback date, 12-hr reminder time, notes, priority & assignment';

  const submitText = document.getElementById('modal-followup-submit-text');
  if (submitText) submitText.innerText = 'Save Follow-up Changes';
  const submitIcon = document.getElementById('modal-followup-submit-icon');
  if (submitIcon) submitIcon.innerText = 'save';

  // Customer display
  const custDisplay = document.getElementById('followup-customer-display');
  if (custDisplay) {
    custDisplay.innerHTML = '<span class="text-slate-900 font-bold">' + (fu.customerName || 'Customer') + '</span><input type="hidden" id="followup-chosen-customer-id" value="' + (fu.customerId || '') + '">';
  }

  // Date
  const dateInput = document.getElementById('followup-date');
  if (dateInput) {
    dateInput.value = fu.date || new Date().toISOString().split('T')[0];
  }

  // Parse 12-hour time
  let hourStr = '11';
  let minStr = '00';
  let ampmStr = 'AM';
  if (fu.time) {
    const tMatch = fu.time.match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/i);
    if (tMatch) {
      hourStr = String(parseInt(tMatch[1], 10)).padStart(2, '0');
      minStr = tMatch[2];
      if (tMatch[3]) {
        ampmStr = tMatch[3].toUpperCase();
      } else {
        const h = parseInt(tMatch[1], 10);
        ampmStr = h >= 12 ? 'PM' : 'AM';
        hourStr = String(h % 12 || 12).padStart(2, '0');
      }
    }
  }
  const hourEl = document.getElementById('followup-hour');
  const minEl = document.getElementById('followup-minute');
  const ampmEl = document.getElementById('followup-ampm');
  if (hourEl) hourEl.value = hourStr;
  if (minEl) minEl.value = minStr;
  if (ampmEl) ampmEl.value = ampmStr;

  // Priority & Channel
  const prioEl = document.getElementById('followup-priority');
  if (prioEl) prioEl.value = fu.priority || 'NORMAL';
  const chanEl = document.getElementById('followup-channel');
  if (chanEl) chanEl.value = fu.channel || 'WHATSAPP';

  // Notes / Reason
  const notesEl = document.getElementById('followup-notes');
  if (notesEl) notesEl.value = fu.reason || '';

  // Staff Assignment Select
  const staffSelect = document.getElementById('followup-staff-select');
  if (staffSelect) {
    staffSelect.value = fu.assignedTo || 'staff_01';
    staffSelect.disabled = false;
    staffSelect.classList.remove('opacity-75', 'cursor-not-allowed');
  }

  // Payment pending fields
  const payToggle = document.getElementById('modal-followup-pay-pending-toggle');
  const payFields = document.getElementById('modal-followup-pay-fields');
  const isPay = Boolean(fu.isPaymentPending);
  if (payToggle) payToggle.checked = isPay;
  if (payFields) payFields.classList.toggle('hidden', !isPay);

  const payAmt = document.getElementById('modal-followup-pay-amount');
  if (payAmt) payAmt.value = fu.paymentAmount || '';
  const payShipping = document.getElementById('modal-followup-pay-shipping');
  if (payShipping) payShipping.value = fu.shippingAmount || '';
  const payMode = document.getElementById('modal-followup-pay-mode');
  if (payMode) payMode.value = fu.paymentMode || 'UPI';
  const payAdv = document.getElementById('modal-followup-pay-advance');
  if (payAdv) payAdv.value = fu.advancePayment || '';
  const quoted = document.getElementById('modal-followup-quoted-items');
  if (quoted) quoted.value = fu.quotedItems || '';

  const dupWarn = document.getElementById('followup-duplicate-warning');
  if (dupWarn) dupWarn.classList.add('hidden');

  if (typeof updateFollowUpTimePreview === 'function') updateFollowUpTimePreview();
  if (typeof openModal === 'function') openModal('modal-followup');
}
window.openEditFollowupModal = openEditFollowupModal;

function openFollowUpModal(prefillCustomerId = null) {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('followups', 'create')) {
    if (typeof showToast === 'function') {
      showToast('Permission Denied', 'Your assigned role does not have permission to schedule follow-ups.', 'lock', 'rose');
    }
    return;
  }
  const currentUser = getCurrentUser();
  const isAdmin = (currentUser.role === 'admin' || currentUser.id === 'admin' || currentUser.staffId === 'admin');

  const cId = prefillCustomerId || ACTIVE_CUSTOMER_ID || (CRM_STATE.customers[0] ? CRM_STATE.customers[0].id : null);
  ACTIVE_CUSTOMER_ID = cId;
  const customer = (CRM_STATE.customers || []).find(c => c.id === cId);
  const query = (CRM_STATE.queries || []).find(q => q.customerId === cId);

  // Set Customer Display
  const custDisplay = document.getElementById('followup-customer-display');
  if (custDisplay) {
    if (prefillCustomerId && customer) {
      custDisplay.innerHTML = `<span class="text-slate-900 font-bold">${customer.name} (${customer.whatsapp || customer.phone || 'WhatsApp'})</span><input type="hidden" id="followup-chosen-customer-id" value="${customer.id}">`;
    } else if (CRM_STATE.customers && CRM_STATE.customers.length > 0) {
      custDisplay.innerHTML = `
        <select id="followup-chosen-customer-id" onchange="ACTIVE_CUSTOMER_ID = this.value; checkDuplicateFollowup(this.value);" class="w-full bg-transparent font-bold text-slate-800 text-xs focus:outline-none cursor-pointer">
          ${CRM_STATE.customers.map(c => `
            <option value="${c.id}" ${c.id === cId ? 'selected' : ''}>${c.name} (${c.whatsapp || c.phone || 'No Phone'})</option>
          `).join('')}
        </select>
      `;
    } else {
      custDisplay.innerHTML = `<span class="text-slate-900 font-bold">${customer ? (customer.name + ' (' + (customer.whatsapp || customer.phone) + ')') : 'Priya Sundaram (+91 98401 23456)'}</span><input type="hidden" id="followup-chosen-customer-id" value="${cId || 'cust_101'}">`;
    }
  }

  // Pre-fill Assigned Staff Dropdown
  const staffSelect = document.getElementById('followup-staff-select');
  if (staffSelect) {
    const currentStaffId = !isAdmin
      ? (currentUser.staffId || currentUser.id)
      : (query ? query.assignedTo : 'staff_01');
    staffSelect.value = currentStaffId || 'staff_01';

    // If current user is not admin, lock the staff selector to themselves
    if (!isAdmin) {
      staffSelect.disabled = true;
      staffSelect.classList.add('opacity-75', 'cursor-not-allowed');
    } else {
      staffSelect.disabled = false;
      staffSelect.classList.remove('opacity-75', 'cursor-not-allowed');
    }
  }

  // Duplicate Active Follow-up Pre-Flight Check
  checkDuplicateFollowup(cId);

  // Set default date to today
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  const dateStr = `${year}-${month}-${day}`;

  const dateInput = document.getElementById('followup-date');
  if (dateInput) {
    dateInput.value = dateStr;
    dateInput.min = dateStr;
  }

  // 12-hour time calculation rounded to next 5 minutes
  let hours = now.getHours();
  let minutes = Math.ceil(now.getMinutes() / 5) * 5;
  if (minutes >= 60) {
    hours = (hours + 1) % 24;
    minutes = 0;
  }
  const ampm = hours >= 12 ? 'PM' : 'AM';
  let hour12 = hours % 12 || 12;

  const hourEl = document.getElementById('followup-hour');
  const minEl = document.getElementById('followup-minute');
  const ampmEl = document.getElementById('followup-ampm');
  if (hourEl) hourEl.value = String(hour12).padStart(2, '0');
  if (minEl) minEl.value = String(minutes).padStart(2, '0');
  if (ampmEl) ampmEl.value = ampm;

  // Defaults for Priority and Channel
  const prioEl = document.getElementById('followup-priority');
  if (prioEl) prioEl.value = 'NORMAL';
  const chanEl = document.getElementById('followup-channel');
  if (chanEl) chanEl.value = 'WHATSAPP';

  // Reset or pre-fill Payment Pending fields
  const payToggle = document.getElementById('modal-followup-pay-pending-toggle');
  const payFields = document.getElementById('modal-followup-pay-fields');
  const payAmt = document.getElementById('modal-followup-pay-amount');
  const payShipping = document.getElementById('modal-followup-pay-shipping');
  const payMode = document.getElementById('modal-followup-pay-mode');
  const payAdvance = document.getElementById('modal-followup-pay-advance');
  const payItems = document.getElementById('modal-followup-quoted-items');
  if (payToggle) {
    payToggle.checked = Boolean(query?.isPaymentPending);
  }
  if (payFields) {
    if (query?.isPaymentPending) {
      payFields.classList.remove('hidden');
    } else {
      payFields.classList.add('hidden');
    }
  }
  if (payAmt) payAmt.value = query?.paymentAmount || '';
  if (payShipping) payShipping.value = query?.shippingAmount || '';
  if (payMode) {
    payMode.value = query?.paymentMode || 'UPI';
    handleModalPayModeChange(payMode.value);
  }
  if (payAdvance) payAdvance.value = query?.advancePayment || '';
  if (payItems) payItems.value = query?.quotedItems || '';

  updateFollowUpTimePreview();
  if (prefillCustomerId) {
    if (typeof selectCustomerChat === 'function') selectCustomerChat(prefillCustomerId);
    if (typeof switchView === 'function') switchView('inbox');
  }
}

function handleModalPayModeChange(val) {
  const adv = document.getElementById('modal-pay-advance-wrapper');
  if (adv) {
    if (val === 'COD_ADVANCE') {
      adv.classList.remove('hidden');
      handleModalPayCalc();
    } else {
      adv.classList.add('hidden');
    }
  }
}
window.handleModalPayModeChange = handleModalPayModeChange;

function handleModalPayCalc() {
  const total = parseFloat(document.getElementById('modal-followup-pay-amount')?.value || 0) || 0;
  const shipping = parseFloat(document.getElementById('modal-followup-pay-shipping')?.value || 0) || 0;
  const advance = parseFloat(document.getElementById('modal-followup-pay-advance')?.value || 0) || 0;
  const balance = Math.max(0, (total + shipping) - advance);
  const balEl = document.getElementById('modal-pay-balance-val');
  if (balEl) {
    balEl.innerText = `₹${balance.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  }
}
window.handleModalPayCalc = handleModalPayCalc;

function updateFollowUpTimePreview() {
  const dateVal = document.getElementById('followup-date')?.value;
  const hourVal = document.getElementById('followup-hour')?.value || '11';
  const minVal = document.getElementById('followup-minute')?.value || '00';
  const ampmVal = document.getElementById('followup-ampm')?.value || 'AM';

  const previewEl = document.getElementById('followup-preview-text');
  if (!previewEl) return;

  if (dateVal) {
    const parts = dateVal.split('-');
    if (parts.length === 3) {
      const d = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
      const dayName = d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
      previewEl.innerText = `${dayName} at ${hourVal}:${minVal} ${ampmVal}`;
    } else {
      previewEl.innerText = `${dateVal} at ${hourVal}:${minVal} ${ampmVal}`;
    }
  } else {
    previewEl.innerText = `${hourVal}:${minVal} ${ampmVal}`;
  }
}

function setFollowUpQuickDate(daysAhead) {
  const target = new Date();
  target.setDate(target.getDate() + daysAhead);
  const year = target.getFullYear();
  const month = String(target.getMonth() + 1).padStart(2, '0');
  const day = String(target.getDate()).padStart(2, '0');
  const dateInput = document.getElementById('followup-date');
  if (dateInput) {
    dateInput.value = `${year}-${month}-${day}`;
  }
  updateFollowUpTimePreview();
}

function setFollowUpQuickTime(preset) {
  const hourEl = document.getElementById('followup-hour');
  const minEl = document.getElementById('followup-minute');
  const ampmEl = document.getElementById('followup-ampm');
  if (!hourEl || !minEl || !ampmEl) return;

  const now = new Date();
  if (preset === 'NOW') {
    let h = now.getHours();
    let m = Math.ceil(now.getMinutes() / 5) * 5;
    if (m >= 60) { h = (h + 1) % 24; m = 0; }
    ampmEl.value = h >= 12 ? 'PM' : 'AM';
    let h12 = h % 12 || 12;
    hourEl.value = String(h12).padStart(2, '0');
    minEl.value = String(m).padStart(2, '0');
  } else if (preset === 'PLUS_1H') {
    let h = (now.getHours() + 1) % 24;
    let m = Math.ceil(now.getMinutes() / 5) * 5;
    if (m >= 60) { h = (h + 1) % 24; m = 0; }
    ampmEl.value = h >= 12 ? 'PM' : 'AM';
    let h12 = h % 12 || 12;
    hourEl.value = String(h12).padStart(2, '0');
    minEl.value = String(m).padStart(2, '0');
  } else if (preset === 'MORNING') {
    hourEl.value = '10';
    minEl.value = '00';
    ampmEl.value = 'AM';
  } else if (preset === 'EVENING') {
    hourEl.value = '05';
    minEl.value = '00';
    ampmEl.value = 'PM';
  }
  updateFollowUpTimePreview();
}

function handleFollowupReasonSelect(val) {
  const notesEl = document.getElementById('followup-notes');
  if (!notesEl) return;
  if (val === 'other') {
    notesEl.value = '';
    notesEl.placeholder = 'Type custom conversation notes & callback instructions here...';
    notesEl.focus();
  } else {
    notesEl.value = val;
  }
}

function appendFollowUpNoteTemplate(text) {
  const notesEl = document.getElementById('followup-notes');
  if (!notesEl) return;
  const current = notesEl.value.trim();
  if (!current || current === 'other') {
    notesEl.value = text;
  } else {
    notesEl.value = `${current} ${text}`;
  }
  notesEl.focus();
}

function checkDuplicateFollowup(cId) {
  const dupWarning = document.getElementById('followup-duplicate-warning');
  const dupText = document.getElementById('followup-duplicate-text');
  if (!dupWarning || !dupText) return;
  const existing = (CRM_STATE.followups || []).find(f => f && (f.customerId === cId || String(f.customerId) === String(cId)) && f.status === 'PENDING');
  if (existing) {
    dupWarning.classList.remove('hidden');
    dupText.innerText = `Customer already has an active follow-up (${existing.id}) scheduled for ${existing.date} at ${existing.time} with ${existing.assignedTo}. You may reschedule or create an additional follow-up.`;
  } else {
    dupWarning.classList.add('hidden');
  }
}
window.checkDuplicateFollowup = checkDuplicateFollowup;

function handleCreateFollowup(event) {
  event.preventDefault();
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('followups', 'create')) {
    if (typeof showToast === 'function') {
      showToast('Permission Denied', 'Your assigned role does not have permission to schedule follow-ups.', 'lock', 'rose');
    }
    return;
  }
  const currentUser = getCurrentUser();
  const chosenCustId = document.getElementById('followup-chosen-customer-id')?.value || ACTIVE_CUSTOMER_ID;
  const date = document.getElementById('followup-date')?.value || new Date().toISOString().split('T')[0];
  const hour = document.getElementById('followup-hour')?.value || '11';
  const min = document.getElementById('followup-minute')?.value || '00';
  const ampm = document.getElementById('followup-ampm')?.value || 'AM';
  const formattedTime = `${hour}:${min} ${ampm}`;
  const notes = document.getElementById('followup-notes')?.value?.trim() || 'Follow-up callback scheduled';
  const priority = document.getElementById('followup-priority')?.value || 'NORMAL';
  const channel = document.getElementById('followup-channel')?.value || 'WHATSAPP';
  const assignedStaff = document.getElementById('followup-staff-select')?.value || (currentUser.staffId || currentUser.id || 'staff_01');

  // Payment Pending Fields
  const isPayPending = document.getElementById('modal-followup-pay-pending-toggle')?.checked || false;
  const payAmt = parseFloat(document.getElementById('modal-followup-pay-amount')?.value || 0);
  const payShipping = parseFloat(document.getElementById('modal-followup-pay-shipping')?.value || 0);
  const payMode = document.getElementById('modal-followup-pay-mode')?.value || 'UPI';
  const payAdvance = parseFloat(document.getElementById('modal-followup-pay-advance')?.value || 0);
  const quotedItems = document.getElementById('modal-followup-quoted-items')?.value?.trim() || '';

  const editId = document.getElementById('followup-edit-id')?.value;
  if (editId) {
    if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('followups', 'edit')) {
      if (typeof showToast === 'function') {
        showToast('Permission Denied', 'Your assigned role does not have permission to edit follow-ups.', 'lock', 'rose');
      }
      return;
    }
    const fu = (CRM_STATE.followups || []).find(f => f && f.id === editId);
    if (fu) {
      fu.date = date;
      fu.time = formattedTime;
      fu.reason = notes;
      fu.priority = priority;
      fu.channel = channel;
      fu.assignedTo = assignedStaff;
      fu.isPaymentPending = isPayPending;
      fu.paymentAmount = payAmt;
      fu.shippingAmount = payShipping;
      fu.paymentMode = payMode;
      fu.advancePayment = (payMode === 'COD_ADVANCE') ? payAdvance : 0;
      fu.paymentDueDate = isPayPending ? date : (fu.paymentDueDate || '');
      fu.paymentNotes = isPayPending ? notes : (fu.paymentNotes || '');
      fu.quotedItems = quotedItems;

      const query = (CRM_STATE.queries || []).find(q => q.customerId === fu.customerId || q.id === fu.queryId);
      if (query) {
        query.callbackDate = date;
        query.callbackTime = formattedTime;
        query.statusNotes = notes;
        if (isPayPending) {
          query.isPaymentPending = true;
          query.paymentAmount = payAmt;
          query.shippingAmount = payShipping;
          query.paymentMode = payMode;
          query.advancePayment = (payMode === 'COD_ADVANCE') ? payAdvance : 0;
          query.paymentDueDate = date;
          query.paymentNotes = notes;
          query.quotedItems = quotedItems;
        }
      }

      fetch('api.php?action=save_followup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(fu)
      }).catch(() => { });

      saveCRMState();
      closeModal('modal-followup');
      showToast('Follow-up Updated', 'Saved changes for ' + (fu.customerName || 'customer'), 'task_alt', 'emerald');
      updateFollowupsKPICounters();
      filterFollowupsCards();
      if (typeof filterPaymentPendingCards === 'function') filterPaymentPendingCards();
      if (typeof renderInbox === 'function') renderInbox();
      return;
    }
  }


  const customer = (CRM_STATE.customers || []).find(c => c.id === chosenCustId) || (CRM_STATE.customers && CRM_STATE.customers[0]) || { id: chosenCustId || 'cust_101', name: 'Customer' };
  const query = (CRM_STATE.queries || []).find(q => q.customerId === customer.id);

  const newFollowup = {
    id: `FU-2026-00${(CRM_STATE.followups || []).length + 101}`,
    queryId: query ? query.id : 'Q-2026-0000',
    customerId: customer.id,
    customerName: customer.name,
    assignedTo: assignedStaff,
    date: date,
    time: formattedTime,
    reason: notes,
    status: 'PENDING',
    outcome: 'PENDING',
    priority: priority,
    channel: channel,
    createdAt: new Date().toISOString(),
    isPaymentPending: isPayPending,
    paymentAmount: payAmt,
    shippingAmount: payShipping,
    paymentMode: payMode,
    advancePayment: (payMode === 'COD_ADVANCE') ? payAdvance : 0,
    paymentDueDate: isPayPending ? date : '',
    paymentNotes: isPayPending ? notes : '',
    quotedItems: quotedItems
  };

  (CRM_STATE.followups = CRM_STATE.followups || []).unshift(newFollowup);
  if (query) {
    const oldSt = query.status || 'NEW';
    query.status = 'FOLLOW_UP';
    if (isPayPending) {
      query.isPaymentPending = true;
      query.paymentAmount = payAmt;
      query.shippingAmount = payShipping;
      query.paymentMode = payMode;
      query.advancePayment = (payMode === 'COD_ADVANCE') ? payAdvance : 0;
      query.paymentDueDate = date;
      query.paymentNotes = notes;
      query.quotedItems = quotedItems;
    }
    const actor = currentUser.name || (ACTIVE_ROLE === 'admin' ? 'Super Admin' : 'Staff');
    const nowObj = new Date();
    const timeFormatted = nowObj.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) + ' at ' + nowObj.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
    query.statusLastEditedBy = actor;
    query.statusLastEditedAt = timeFormatted;
    query.statusNotes = notes;
    query.statusHistory = query.statusHistory || [];
    query.statusHistory.unshift({
      action: (oldSt === 'FOLLOW_UP') ? 'FOLLOWUP_RESCHEDULED' : 'FOLLOWUP_SCHEDULED',
      from: oldSt,
      to: 'FOLLOW_UP',
      by: actor,
      at: timeFormatted,
      followupDate: date,
      followupTime: formattedTime,
      assignedTo: assignedStaff,
      notes: notes,
      timestamp: nowObj.toISOString()
    });
  }

  const actor = currentUser.name || 'Staff';
  logAudit('FOLLOWUP_SCHEDULED', 'FOLLOWUP', `Scheduled follow-up for ${customer.name} on ${date} at ${formattedTime} via ${channel} (Priority: ${priority}, Staff: ${assignedStaff}${isPayPending ? ', Payment Pending: ₹' + payAmt : ''})`);

  // Asynchronously synchronize follow-up with MySQL Database
  fetch('api.php?action=save_followup', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(newFollowup)
  }).catch(() => { });

  saveCRMState();
  closeModal('modal-followup');
  if (isPayPending) {
    showToast('Payment Follow-up Scheduled', `Payment Pending ₹${payAmt.toFixed(2)} scheduled for ${date} (${assignedStaff})`, 'payments', 'amber');
  } else {
    showToast('Follow-up Scheduled', `Reminder set for ${date} at ${formattedTime} (${assignedStaff})`, 'event', 'blue');
  }

  updateFollowupsKPICounters();
  filterFollowupsCards();
  renderInbox();
}

function openFollowupOutcomeModal(fuId) {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('followups', 'edit')) {
    if (typeof showToast === 'function') {
      showToast('Permission Denied', 'Your assigned role does not have permission to edit follow-up outcomes.', 'lock', 'rose');
    }
    return;
  }
  const fu = (CRM_STATE.followups || []).find(f => f.id === fuId);
  if (!fu) return;

  const idInput = document.getElementById('outcome-followup-id');
  const badgeId = document.getElementById('outcome-badge-id');
  const custName = document.getElementById('outcome-customer-name');
  const reasonEl = document.getElementById('outcome-original-reason');
  const staffBadge = document.getElementById('outcome-assigned-badge');
  const notesText = document.getElementById('outcome-notes');
  const nextDateInput = document.getElementById('outcome-next-date');
  const nextTimeInput = document.getElementById('outcome-next-time');

  if (idInput) idInput.value = fu.id;
  if (badgeId) badgeId.innerText = fu.id;
  if (custName) custName.innerText = fu.customerName;
  if (reasonEl) reasonEl.innerText = `Note: ${fu.reason}`;
  if (staffBadge) staffBadge.innerText = `Assigned: ${fu.assignedTo}`;
  if (notesText) notesText.value = '';

  // Default next follow-up date to tomorrow
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  if (nextDateInput) nextDateInput.value = tomorrow.toISOString().split('T')[0];
  if (nextTimeInput) nextTimeInput.value = '11:00 AM';

  // Reset radio cards
  const radios = document.getElementsByName('followup_outcome');
  radios.forEach(r => { r.checked = (r.value === 'INTERESTED'); });
  toggleOutcomeNextScheduler('INTERESTED');

  openModal('modal-followup-outcome');
}

function toggleOutcomeNextScheduler(val) {
  const scheduler = document.getElementById('outcome-next-scheduler');
  if (!scheduler) return;
  if (val === 'FOLLOWUP_AGAIN') {
    scheduler.classList.remove('hidden');
  } else {
    scheduler.classList.add('hidden');
  }
}

function handleSaveFollowupOutcome(event) {
  event.preventDefault();
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('followups', 'edit')) {
    if (typeof showToast === 'function') {
      showToast('Permission Denied', 'Your assigned role does not have permission to edit follow-up outcomes.', 'lock', 'rose');
    }
    return;
  }
  const fuId = document.getElementById('outcome-followup-id')?.value;
  const radios = document.getElementsByName('followup_outcome');
  let chosenOutcome = 'INTERESTED';
  for (const r of radios) {
    if (r.checked) { chosenOutcome = r.value; break; }
  }
  const notes = document.getElementById('outcome-notes')?.value?.trim() || 'Follow-up completed';

  const fu = (CRM_STATE.followups || []).find(f => f.id === fuId);
  if (!fu) return;

  // 1. Update current follow-up
  fu.status = 'COMPLETED';
  fu.outcome = chosenOutcome;
  fu.outcomeNotes = notes;
  fu.completedAt = new Date().toISOString();

  // 2. Query status side-effects
  const query = CRM_STATE.queries.find(q => q.id === fu.queryId || q.customerId === fu.customerId);
  let nextFuPayload = null;

  if (chosenOutcome === 'ORDER_PLACED') {
    if (query) query.status = 'CONVERTED';
    showToast('Customer Lead Converted!', 'Customer placed order! Opening order booking...', 'verified', 'emerald');
  } else if (chosenOutcome === 'LOST') {
    if (query) query.status = 'LOST';
  } else if (chosenOutcome === 'FOLLOWUP_AGAIN') {
    const nextDate = document.getElementById('outcome-next-date')?.value || new Date().toISOString().split('T')[0];
    const nextTime = document.getElementById('outcome-next-time')?.value || '11:00 AM';
    const nextFu = {
      id: `FU-2026-00${CRM_STATE.followups.length + 102}`,
      queryId: fu.queryId,
      customerId: fu.customerId,
      customerName: fu.customerName,
      assignedTo: fu.assignedTo,
      date: nextDate,
      time: nextTime,
      reason: `Follow-up again: ${notes}`,
      status: 'PENDING',
      outcome: 'PENDING',
      priority: fu.priority || 'NORMAL',
      channel: fu.channel || 'WHATSAPP',
      rescheduledFromId: fu.id,
      createdAt: new Date().toISOString()
    };
    CRM_STATE.followups.unshift(nextFu);
    nextFuPayload = nextFu;
    if (query) {
      const oldSt = query.status || 'FOLLOW_UP';
      query.status = 'FOLLOW_UP';
      const actor = currentUser.name || (ACTIVE_ROLE === 'admin' ? 'Super Admin' : 'Staff');
      const nowObj = new Date();
      const timeFormatted = nowObj.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) + ' at ' + nowObj.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
      query.statusLastEditedBy = actor;
      query.statusLastEditedAt = timeFormatted;
      query.statusNotes = notes ? `Follow-up again: ${notes}` : `Follow-up rescheduled to ${nextDate} at ${nextTime}`;
      query.statusHistory = query.statusHistory || [];
      query.statusHistory.unshift({
        action: 'FOLLOWUP_RESCHEDULED',
        from: oldSt,
        to: 'FOLLOW_UP',
        by: actor,
        at: timeFormatted,
        followupDate: nextDate,
        followupTime: nextTime,
        previousFollowupDate: fu.date,
        previousFollowupTime: fu.time,
        assignedTo: fu.assignedTo,
        notes: notes ? `Follow-up again: ${notes}` : `Follow-up rescheduled to ${nextDate} at ${nextTime}`,
        timestamp: nowObj.toISOString()
      });
    }
  }

  // 3. Post to backend API
  const currentUser = getCurrentUser();
  fetch('api.php?action=log_followup_outcome', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      id: fuId,
      outcome: chosenOutcome,
      notes: notes,
      user: currentUser.name || 'Staff',
      next_followup: nextFuPayload
    })
  }).catch(() => { });

  saveCRMState();
  closeModal('modal-followup-outcome');
  showToast('Follow-up Result Saved', `Outcome marked as ${chosenOutcome}`, 'check_circle', 'emerald');

  updateFollowupsKPICounters();
  filterFollowupsCards();
  updatePaymentPendingKPICounters();
  filterPaymentPendingCards();

  // If order placed, prompt to book order
  if (chosenOutcome === 'ORDER_PLACED') {
    setTimeout(() => {
      ACTIVE_CUSTOMER_ID = fu.customerId;
      if (typeof openConvertOrderModal === 'function') openConvertOrderModal();
    }, 600);
  }
}

function handleReassignFollowup(fuId, newStaffId) {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('followups', 'edit')) {
    if (typeof showToast === 'function') {
      showToast('Permission Denied', 'Your assigned role does not have permission to reassign follow-ups.', 'lock', 'rose');
    }
    return;
  }
  const fu = (CRM_STATE.followups || []).find(f => f.id === fuId);
  if (!fu) return;

  const prevStaff = fu.assignedTo;
  fu.assignedTo = newStaffId;

  logAudit('FOLLOWUP_REASSIGNED', 'FOLLOWUP', `Reassigned follow-up ${fuId} from ${prevStaff} to ${newStaffId}`);

  const currentUser = getCurrentUser();
  fetch('api.php?action=reassign_followup', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      id: fuId,
      assigned_to: newStaffId,
      user: currentUser.name || 'Admin'
    })
  }).catch(() => { });

  saveCRMState();
  showToast('Follow-up Reassigned', `Assigned to ${newStaffId}`, 'published_with_changes', 'blue');
  updateFollowupsKPICounters();
  filterFollowupsCards();
  updatePaymentPendingKPICounters();
  filterPaymentPendingCards();
}

function handleQuickFollowupStatusChange(fuId, newStatusVal) {
  const fu = (CRM_STATE.followups || []).find(f => f.id === fuId);
  if (!fu) return;

  const todayStr = new Date().toISOString().split('T')[0];
  const currentUser = getCurrentUser();
  const actor = currentUser.name || (ACTIVE_ROLE === 'admin' ? 'Super Admin' : 'Staff');

  if (newStatusVal === 'OUTCOME_MODAL') {
    openFollowupOutcomeModal(fuId);
    return;
  }

  if (newStatusVal === 'ORDER_PLACED') {
    fu.status = 'COMPLETED';
    fu.outcome = 'ORDER_PLACED';
    fu.outcomeNotes = 'Marked as Order Placed by ' + actor;
    fu.completedAt = new Date().toISOString();
    const query = (CRM_STATE.queries || []).find(q => q.id === fu.queryId || q.customerId === fu.customerId);
    if (query) query.status = 'CONVERTED';
    showToast('Order Placed! 🏆', `Converted to Order Placed for ${fu.customerName} (Green border active)`, 'verified', 'emerald');
    if (typeof playChime === 'function') playChime('order');
  } else if (newStatusVal === 'LOST') {
    fu.status = 'COMPLETED';
    fu.outcome = 'LOST';
    fu.outcomeNotes = 'Marked as Lost / Cancelled by ' + actor;
    fu.completedAt = new Date().toISOString();
    const query = (CRM_STATE.queries || []).find(q => q.id === fu.queryId || q.customerId === fu.customerId);
    if (query) query.status = 'LOST';
    showToast('Marked as Lost', `Follow-up marked as Lost for ${fu.customerName} (Gray border active)`, 'cancel', 'slate');
  } else if (newStatusVal === 'TODAY') {
    fu.status = 'PENDING';
    fu.outcome = 'PENDING';
    fu.date = todayStr;
    fu.time = '11:00 AM';
    if (fu.isPaymentPending) fu.paymentDueDate = todayStr;
    showToast('Scheduled for Today', `Status updated to Today's Due for ${fu.customerName} (Blue border active)`, 'today', 'blue');
  } else if (newStatusVal === 'UPCOMING') {
    fu.status = 'PENDING';
    fu.outcome = 'PENDING';
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    const tomorrowStr = tomorrow.toISOString().split('T')[0];
    fu.date = tomorrowStr;
    fu.time = '11:00 AM';
    if (fu.isPaymentPending) fu.paymentDueDate = tomorrowStr;
    showToast('Scheduled for Upcoming', `Status updated to Tomorrow/Upcoming for ${fu.customerName} (Purple border active)`, 'upcoming', 'purple');
  }

  saveCRMState();
  fetch('api.php?action=save_followup', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(fu)
  }).catch(() => { });

  updateFollowupsKPICounters();
  filterFollowupsCards();
  updatePaymentPendingKPICounters();
  filterPaymentPendingCards();
}
window.handleQuickFollowupStatusChange = handleQuickFollowupStatusChange;

let ACTIVE_FOLLOWUP_HUB_MODE = 'FOLLOWUPS'; // 'FOLLOWUPS' | 'PAYMENT_PENDING'
let ACTIVE_PAYMENT_PENDING_TAB = 'ALL'; // 'ALL' | 'TODAY' | 'UPCOMING' | 'OVERDUE' | 'COMPLETED' | 'LOST'

function switchFollowupHubMode(mode) {
  ACTIVE_FOLLOWUP_HUB_MODE = mode;
  const viewFollowups = document.getElementById('subview-hub-followups');
  const viewPayment = document.getElementById('subview-hub-payment-pending');
  const tabFollowups = document.getElementById('hub-mode-tab-followups');
  const tabPayment = document.getElementById('hub-mode-tab-payment-pending');

  if (mode === 'FOLLOWUPS') {
    if (viewFollowups) viewFollowups.classList.remove('hidden');
    if (viewPayment) viewPayment.classList.add('hidden');
    if (tabFollowups) tabFollowups.className = "px-5 py-2.5 rounded-xl font-black text-xs flex items-center gap-2 transition-all shadow-sm bg-white text-blue-700 cursor-pointer";
    if (tabPayment) tabPayment.className = "px-5 py-2.5 rounded-xl font-black text-xs flex items-center gap-2 transition-all text-slate-600 hover:text-amber-700 cursor-pointer";
    updateFollowupsKPICounters();
    filterFollowupsCards();
  } else {
    if (viewFollowups) viewFollowups.classList.add('hidden');
    if (viewPayment) viewPayment.classList.remove('hidden');
    if (tabFollowups) tabFollowups.className = "px-5 py-2.5 rounded-xl font-black text-xs flex items-center gap-2 transition-all text-slate-600 hover:text-blue-700 cursor-pointer";
    if (tabPayment) tabPayment.className = "px-5 py-2.5 rounded-xl font-black text-xs flex items-center gap-2 transition-all shadow-sm bg-white text-amber-600 cursor-pointer";
    updatePaymentPendingKPICounters();
    filterPaymentPendingCards();
  }
}
window.switchFollowupHubMode = switchFollowupHubMode;

function setFollowupTabFilter(tab) {
  ACTIVE_FOLLOWUP_TAB = tab;

  // Highlight tab buttons
  const tabs = ['ALL', 'TODAY', 'UPCOMING', 'OVERDUE', 'PAYMENT_PENDING', 'COMPLETED', 'LOST'];
  tabs.forEach(t => {
    const btnId = t === 'PAYMENT_PENDING' ? 'tab-fu-payment-pending' : `tab-fu-${t.toLowerCase()}`;
    const btn = document.getElementById(btnId);
    if (btn) {
      if (t === tab) {
        if (t === 'PAYMENT_PENDING') {
          btn.className = "px-3.5 py-1.5 rounded-xl font-bold bg-white text-amber-600 border border-amber-200/80 shadow-sm transition shrink-0 flex items-center gap-1.5 cursor-pointer";
        } else {
          btn.className = "px-3.5 py-1.5 rounded-xl font-bold bg-blue-600 text-white shadow-sm transition shrink-0 flex items-center gap-1 cursor-pointer";
        }
      } else {
        if (t === 'PAYMENT_PENDING') {
          btn.className = "px-3.5 py-1.5 rounded-xl font-bold bg-slate-100 hover:bg-amber-50 text-slate-700 hover:text-amber-800 transition shrink-0 flex items-center gap-1.5 cursor-pointer";
        } else {
          btn.className = "px-3.5 py-1.5 rounded-xl font-bold bg-slate-100 hover:bg-slate-200 text-slate-700 transition shrink-0 flex items-center gap-1 cursor-pointer";
        }
      }
    }
  });

  // KPI card selection border highlight
  const kpiFuMap = {
    'ALL': { id: 'kpi-card-all', ring: 'ring-orange-500' },
    'TODAY': { id: 'kpi-card-today', ring: 'ring-blue-500' },
    'UPCOMING': { id: 'kpi-card-upcoming', ring: 'ring-purple-500' },
    'OVERDUE': { id: 'kpi-card-overdue', ring: 'ring-rose-500' },
    'PAYMENT_PENDING': { id: 'kpi-card-payment-pending', ring: 'ring-amber-500' },
    'COMPLETED': { id: 'kpi-card-converted', ring: 'ring-emerald-500' },
    'LOST': { id: 'kpi-card-lost', ring: 'ring-slate-500' }
  };
  Object.keys(kpiFuMap).forEach(k => {
    const item = kpiFuMap[k];
    const card = document.getElementById(item.id);
    if (card) {
      card.classList.remove('ring-2', 'ring-indigo-500', 'ring-orange-500', 'ring-blue-500', 'ring-purple-500', 'ring-rose-500', 'ring-amber-500', 'ring-emerald-500', 'ring-slate-500', 'shadow-md');
      if (k === tab) {
        card.classList.add('ring-2', item.ring, 'shadow-md');
      }
    }
  });

  filterFollowupsCards();
}
window.setFollowupTabFilter = setFollowupTabFilter;

function isPayPendingRecord(f) {
  if (!f) return false;
  if (f.isPaymentPending === true || f.isPaymentPending === 1 || f.isPaymentPending === '1' || f.is_payment_pending == 1) return true;
  if (f.paymentAmount && parseFloat(f.paymentAmount) > 0) return true;
  const q = (CRM_STATE.queries || []).find(qry => qry && (qry.id === f.queryId || qry.customerId === f.customerId));
  if (q && (q.isPaymentPending || (q.paymentAmount && parseFloat(q.paymentAmount) > 0))) return true;
  return false;
}
window.isPayPendingRecord = isPayPendingRecord;

function updateFollowupsKPICounters() {
  const all = (CRM_STATE.followups || []).filter(f => f && !(f.reason && f.reason.includes('ytfdw')));
  const currentUser = getCurrentUser();
  const isAdmin = (currentUser.role === 'admin' || currentUser.id === 'admin' || currentUser.staffId === 'admin');

  // Scoped list for current user view
  const curStaffId = String(currentUser.staffId || currentUser.id || '');
  const curUsername = String(currentUser.username || '');
  const curName = String(currentUser.name || '').toLowerCase();

  const scopedList = isAdmin ? all : all.filter(f => {
    const fuAssigned = String(f.assignedTo || '');
    if (fuAssigned === curStaffId || fuAssigned === curUsername || fuAssigned.toLowerCase() === curName) return true;
    const matchingQuery = (CRM_STATE.queries || []).find(q => q && (
      (f.queryId && (q.id === f.queryId || q.id === f.query_id)) ||
      (f.customerId && (q.customerId === f.customerId || q.customer_id === f.customerId || String(q.customerId) === String(f.customerId) || String(q.customer_id) === String(f.customerId)))
    ));
    if (matchingQuery) {
      const qAssigned = String(matchingQuery.assignedTo || matchingQuery.assigned_to || '');
      if (qAssigned === curStaffId || qAssigned === curUsername || qAssigned.toLowerCase() === curName) {
        f.assignedTo = curStaffId;
        return true;
      }
    }
    return false;
  });

  const todayStr = new Date().toISOString().split('T')[0];
  const total = scopedList.length;
  const todayDue = scopedList.filter(f => f.status === 'PENDING' && f.date === todayStr).length;
  const upcoming = scopedList.filter(f => f.status === 'PENDING' && f.date > todayStr).length;
  const overdue = scopedList.filter(f => isFollowupOverdue(f)).length;
  const paymentPendingList = scopedList.filter(f => (f.status === 'PENDING' || !f.status || f.status === 'SCHEDULED') && isPayPendingRecord(f));
  const paymentPendingCount = paymentPendingList.length;
  const paymentPendingTotalAmt = paymentPendingList.reduce((sum, f) => sum + (parseFloat(f.paymentAmount) || 0), 0);
  const converted = scopedList.filter(f => f.status === 'COMPLETED' && f.outcome !== 'LOST').length;
  const lost = scopedList.filter(f => f.outcome === 'LOST').length;

  // Update Top Metric Cards
  const elTotal = document.getElementById('kpi-fu-total');
  const elToday = document.getElementById('kpi-fu-today');
  const elUpcoming = document.getElementById('kpi-fu-upcoming');
  const elOverdue = document.getElementById('kpi-fu-overdue');
  const elPaymentPending = document.getElementById('kpi-fu-payment-pending');
  const elPaymentAmount = document.getElementById('kpi-fu-payment-amount');
  const elConverted = document.getElementById('kpi-fu-converted');
  const elLost = document.getElementById('kpi-fu-lost');

  if (elTotal) elTotal.innerText = total;
  if (elToday) elToday.innerText = todayDue;
  if (elUpcoming) elUpcoming.innerText = upcoming;
  if (elOverdue) elOverdue.innerText = overdue;
  if (elPaymentPending) elPaymentPending.innerText = paymentPendingCount;
  if (elPaymentAmount) elPaymentAmount.innerText = `₹${paymentPendingTotalAmt.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} Total`;
  if (elConverted) elConverted.innerText = converted;
  if (elLost) elLost.innerText = lost;

  // Update Tier 1 Mode Switcher Badges
  const hubBadgeFollowups = document.getElementById('hub-badge-followups-count');
  if (hubBadgeFollowups) hubBadgeFollowups.innerText = total;
  const hubBadgePayment = document.getElementById('hub-badge-payment-pending-count');
  if (hubBadgePayment) hubBadgePayment.innerText = paymentPendingCount;

  // Update Tab Badges
  const tabBadgeToday = document.getElementById('tab-badge-today');
  const tabBadgeOverdue = document.getElementById('tab-badge-overdue');
  const tabBadgePayPending = document.getElementById('tab-badge-payment-pending');
  if (tabBadgeToday) tabBadgeToday.innerText = todayDue;
  if (tabBadgeOverdue) tabBadgeOverdue.innerText = overdue;
  if (tabBadgePayPending) tabBadgePayPending.innerText = paymentPendingCount;

  // Sidebar Follow-up Counter
  const badgeSidebar = document.getElementById('badge-followup-count');
  if (badgeSidebar) {
    const dueCount = overdue + todayDue;
    badgeSidebar.innerText = dueCount > 0 ? `${dueCount} Due` : `${todayDue} Today`;
    if (overdue > 0) {
      badgeSidebar.className = "bg-rose-500/20 text-rose-300 text-[10px] font-bold px-2 py-0.5 rounded-full border border-rose-400/40 animate-pulse";
    } else {
      badgeSidebar.className = "bg-amber-500/20 text-amber-300 border border-amber-500/30 text-[10px] font-bold px-2 py-0.5 rounded-full";
    }
  }

  // Role Header Banner update
  const roleBadge = document.getElementById('followup-role-badge');
  const roleSubtitle = document.getElementById('followup-role-subtitle');
  const staffFilterContainer = document.getElementById('followup-staff-filter-container');

  if (roleBadge) {
    roleBadge.innerText = isAdmin ? '👑 Admin Overview (All Staff)' : `👩‍💼 Staff Workstation (${currentUser.name || currentUser.id})`;
    roleBadge.className = isAdmin
      ? 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-indigo-50 text-indigo-700 border border-indigo-200'
      : 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-emerald-50 text-emerald-800 border border-emerald-200';
  }
  if (roleSubtitle) {
    roleSubtitle.innerText = isAdmin
      ? 'Admin Control: Full visibility across all 4 staff queues, customer promises, response rates & conversions.'
      : `Staff View: Displaying customer follow-ups and inquiries assigned to you (${currentUser.name || currentUser.id}).`;
  }
  if (staffFilterContainer) {
    if (!isAdmin) {
      staffFilterContainer.innerHTML = `
        <span class="inline-flex items-center gap-1.5 bg-slate-100 border border-slate-200 text-slate-700 text-xs font-bold px-3 py-2 rounded-2xl">
          <span class="material-symbols-outlined text-[15px] text-emerald-600">lock</span>
          <span>${currentUser.name || currentUser.id}</span>
        </span>
      `;
    }
  }

  // Also update Payment Pending Counters
  updatePaymentPendingKPICounters();
}
window.updateFollowupsKPICounters = updateFollowupsKPICounters;

function updatePaymentPendingKPICounters() {
  const all = (CRM_STATE.followups || []).filter(f => f && !(f.reason && f.reason.includes('ytfdw')));
  const currentUser = getCurrentUser();
  const isAdmin = (currentUser.role === 'admin' || currentUser.id === 'admin' || currentUser.staffId === 'admin');

  // RBAC scope
  const scopedList = isAdmin ? all : all.filter(f => f.assignedTo === currentUser.id || f.assignedTo === currentUser.staffId);
  const payRecords = scopedList.filter(f => isPayPendingRecord(f));

  const todayStr = new Date().toISOString().split('T')[0];

  const totalPendingList = payRecords.filter(f => (f.status === 'PENDING' || !f.status || f.status === 'SCHEDULED'));
  const todayDueList = payRecords.filter(f => (f.status === 'PENDING' || !f.status || f.status === 'SCHEDULED') && (f.paymentDueDate === todayStr || f.date === todayStr));
  const upcomingList = payRecords.filter(f => (f.status === 'PENDING' || !f.status || f.status === 'SCHEDULED') && ((f.paymentDueDate || f.date) > todayStr));
  const overdueList = payRecords.filter(f => (f.status === 'PENDING' || !f.status || f.status === 'SCHEDULED') && isFollowupOverdue(f));
  const convertedList = payRecords.filter(f => f.status === 'COMPLETED' && f.outcome !== 'LOST');
  const lostList = payRecords.filter(f => f.outcome === 'LOST');

  const sumAmt = (list) => list.reduce((sum, f) => sum + (parseFloat(f.paymentAmount) || 0), 0);

  const totalCount = payRecords.length;
  const totalAmount = sumAmt(payRecords);

  const todayCount = todayDueList.length;
  const todayAmount = sumAmt(todayDueList);

  const upcomingCount = upcomingList.length;
  const upcomingAmount = sumAmt(upcomingList);

  const overdueCount = overdueList.length;
  const overdueAmount = sumAmt(overdueList);

  const convertedCount = convertedList.length;
  const convertedAmount = sumAmt(convertedList);

  const lostCount = lostList.length;
  const lostAmount = sumAmt(lostList);

  const fmt = (amt) => `₹${amt.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  const setInner = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.innerText = val;
  };

  setInner('kpi-pay-total-count', totalCount);
  setInner('kpi-pay-total-amount', `${fmt(totalAmount)} Total`);

  setInner('kpi-pay-today-count', todayCount);
  setInner('kpi-pay-today-amount', `${fmt(todayAmount)} Due`);

  setInner('kpi-pay-upcoming-count', upcomingCount);
  setInner('kpi-pay-upcoming-amount', `${fmt(upcomingAmount)} Promised`);

  setInner('kpi-pay-overdue-count', overdueCount);
  setInner('kpi-pay-overdue-amount', `${fmt(overdueAmount)} Overdue`);

  setInner('kpi-pay-converted-count', convertedCount);
  setInner('kpi-pay-converted-amount', `${fmt(convertedAmount)} Collected`);

  setInner('kpi-pay-lost-count', lostCount);
  setInner('kpi-pay-lost-amount', `${fmt(lostAmount)} Cancelled`);

  // Sub-tab ribbon badges
  setInner('tab-badge-pay-today', todayCount);
  setInner('tab-badge-pay-overdue', overdueCount);

  // Top header badge
  setInner('hub-badge-payment-pending-count', totalCount);
}
window.updatePaymentPendingKPICounters = updatePaymentPendingKPICounters;

