function generateSampleAWB(courier) {
  const cleanCourier = (courier || 'ST').toUpperCase();
  const randNum = Math.floor(10000000 + Math.random() * 90000000);
  if (cleanCourier.includes('DTDC')) return `D${randNum}`;
  if (cleanCourier.includes('DELHIVERY')) return `DEL${randNum}`;
  if (cleanCourier.includes('BLUE')) return `BD${randNum}`;
  if (cleanCourier.includes('ST')) return `STC${randNum}`;
  if (cleanCourier.includes('PROFESSIONAL')) return `TPC${randNum}`;
  if (cleanCourier.includes('POST')) return `EM${randNum}IN`;
  return `TRK-${randNum}`;
}
window.generateSampleAWB = generateSampleAWB;

function generateCourierTrackingURL(courier, trackingId) {
  const c = (courier || '').toLowerCase();
  const id = encodeURIComponent((trackingId || '').trim());
  if (!id) return '';

  if (c.includes('dtdc')) {
    return `https://www.dtdc.in/tracking/shipment-tracking.asp?strCnno=${id}`;
  }
  if (c.includes('delhivery')) {
    return `https://www.delhivery.com/track/package/${id}`;
  }
  if (c.includes('blue')) {
    return `https://www.bluedart.com/tracking?track=${id}`;
  }
  if (c.includes('st') || c.includes('stcourier')) {
    return `https://stcourier.com/track/search?awb=${id}`;
  }
  if (c.includes('professional') || c.includes('tpc')) {
    return `https://www.tpcindia.com/track.aspx?awb=${id}`;
  }
  if (c.includes('post') || c.includes('speed')) {
    return `https://www.indiapost.gov.in/_layouts/15/dpt.cpt.trackconsignment/trackconsignment.aspx?id=${id}`;
  }
  return `https://track.aftership.com/${id}`;
}
window.generateCourierTrackingURL = generateCourierTrackingURL;

function updateShippingWhatsAppPreview() {
  const courier = (document.getElementById('ship-courier-name')?.value || '').trim() || 'Courier';
  const trackingId = (document.getElementById('ship-tracking-id')?.value || '').trim();
  const url = (document.getElementById('ship-tracking-url')?.value || '').trim();
  const ord = ACTIVE_SHIPPING_DISPATCH_ORDER;

  const previewEl = document.getElementById('ship-wa-preview-text');
  if (previewEl && ord) {
    const trackingDisplay = trackingId || '[Pending Courier Docket / Slip]';
    const urlDisplay = url || (trackingId ? generateCourierTrackingURL(courier, trackingId) : '[Link will be generated when AWB is entered]');
    previewEl.innerText = `🚚 *DISPATCH & TRACKING UPDATE*\nOrder #${ord.id}\nCourier: ${courier}\nTracking ID: ${trackingDisplay}\nTrack here: ${urlDisplay}`;
  }
}
window.updateShippingWhatsAppPreview = updateShippingWhatsAppPreview;

/**
 * Confirms Shipping Dispatch:
 * Saves courier name, shipping ID, shipping URL, updates status to SHIPPED,
 * syncs to MySQL, sends WhatsApp notification, and re-renders table!
 */
function confirmShippingDispatch() {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('orders', 'edit')) {
    if (typeof showToast === 'function') showToast('Permission Denied', 'Your assigned role does not have permission to confirm shipping dispatch.', 'lock', 'rose');
    return;
  }
  const ord = ACTIVE_SHIPPING_DISPATCH_ORDER;
  if (!ord) return;

  const courierName = (document.getElementById('ship-courier-name')?.value || '').trim();
  const trackingId = (document.getElementById('ship-tracking-id')?.value || '').trim();
  const trackingUrl = (document.getElementById('ship-tracking-url')?.value || '').trim();
  const sendWhatsApp = document.getElementById('ship-send-whatsapp')?.checked;

  if (!courierName) {
    showToast('Courier Required', 'Please enter or select a courier name.', 'warning', 'amber');
    document.getElementById('ship-courier-name')?.focus();
    return;
  }
  if (!trackingId) {
    showToast('Shipping ID Required', 'Please enter the Shipping ID / Tracking Number (AWB).', 'warning', 'amber');
    document.getElementById('ship-tracking-id')?.focus();
    return;
  }

  const oldStatus = ord.orderStatus || ord.order_status;

  // Update order object
  ord.orderStatus = 'SHIPPED';
  ord.order_status = 'SHIPPED';
  ord.courierName = courierName;
  ord.courier_name = courierName;
  ord.trackingNumber = trackingId;
  ord.tracking_number = trackingId;
  ord.shippingUrl = trackingUrl;
  ord.shipping_url = trackingUrl;

  // Persist to MySQL
  fetch('api.php?action=update_order_status', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      id: ord.id,
      order_id: ord.id,
      order_status: 'SHIPPED',
      status: 'SHIPPED',
      courier_name: courierName,
      tracking_number: trackingId,
      shipping_url: trackingUrl,
      user: CURRENT_USER?.name || 'Super Admin'
    })
  }).catch(() => { });

  // Send WhatsApp dispatch notification if checked
  if (sendWhatsApp) {
    const custId = ord.customerId || ACTIVE_CUSTOMER_ID;
    const dispatchMsg = `🚚 *YOUR PARCEL HAS BEEN DISPATCHED!* 📦\n━━━━━━━━━━━━━━━━━━━━━━\n📦 *Order ID:* #${ord.id}\n👤 *Customer:* ${ord.customerName}\n\n🏢 *Courier Partner:* *${courierName}*\n🔢 *Shipping / AWB ID:* \`${trackingId}\`\n${trackingUrl ? `🔗 *Live Tracking Link:*\n${trackingUrl}\n` : ''}📍 *Delivery Address:*\n${ord.shippingAddress || 'Customer Address'}\n━━━━━━━━━━━━━━━━━━━━━━\nYour parcel is on its way! Expected delivery within 2–4 business days. Thank you for shopping with GRM Garments! ✨`;

    if (!CRM_STATE.conversations[custId]) {
      CRM_STATE.conversations[custId] = [];
    }
    CRM_STATE.conversations[custId].push({
      id: Date.now(),
      sender: 'staff',
      text: dispatchMsg,
      type: 'text',
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      status: 'SENT'
    });
  }

  logAudit('ORDER_SHIPPED', 'ORDERS', `Order ${ord.id} marked as SHIPPED via ${courierName} (AWB: ${trackingId})`);
  saveCRMState();
  renderOrdersDashboard();
  renderOrdersHistoryTable();

  closeModal('modal-order-shipping-dispatch');
  ACTIVE_SHIPPING_DISPATCH_ORDER = null;

  showToast('Order Dispatched', `Order ${ord.id} marked as Shipped via ${courierName}.`, 'local_shipping', 'emerald');
  if (typeof playChime === 'function') playChime('order');
}
window.confirmShippingDispatch = confirmShippingDispatch;

// Robust CSV download helper using Blob and UTF-8 BOM
function downloadOrdersCSVBlob(filename, csvContent) {
  try {
    const bom = '\uFEFF';
    const blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", filename);
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => {
      try { URL.revokeObjectURL(url); } catch (e) { }
    }, 1500);
    return true;
  } catch (err) {
    console.error('Blob download failed, using fallback:', err);
    try {
      const encodedUri = encodeURI("data:text/csv;charset=utf-8,\uFEFF" + csvContent);
      const link = document.createElement("a");
      link.setAttribute("href", encodedUri);
      link.setAttribute("download", filename);
      link.style.display = 'none';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      return true;
    } catch (e2) {
      console.error('Download fallback failed:', e2);
      return false;
    }
  }
}

// 1. WhatsApp Sales & Orders Dashboard Full Report
function downloadOrdersDashboardReport() {
  // If user is currently viewing the Orders History submodule, intelligently route to Orders History CSV
  const isHistoryView = (typeof ACTIVE_ORDERS_SUBMODULE !== 'undefined' && ACTIVE_ORDERS_SUBMODULE === 'history') ||
    (window.location.hash && window.location.hash.includes('history')) ||
    (document.getElementById('subview-orders-history') && !document.getElementById('subview-orders-history').classList.contains('hidden'));
  if (isHistoryView) {
    return downloadOrdersHistoryCSV();
  }

  const fromVal = document.getElementById('orders-filter-date-from')?.value || '';
  const toVal = document.getElementById('orders-filter-date-to')?.value || '';
  const orders = (typeof getOrdersDateFilteredList === 'function') ? getOrdersDateFilteredList() : (CRM_STATE?.orders || []);

  let overallRevenue = 0;
  let paidOnlineTotal = 0;
  let codDueTotal = 0;

  orders.forEach(o => {
    const total = parseFloat(o.grandTotal || o.grand_total) || 0;
    overallRevenue += total;
    const isCod = o.paymentMethod === 'COD' || o.payment_method === 'COD';
    if (isCod) {
      const codAdv = parseFloat(o.codAdvance || o.cod_advance) || 200;
      const codDue = o.codBalanceDue !== undefined ? parseFloat(o.codBalanceDue) : Math.max(0, total - codAdv);
      paidOnlineTotal += codAdv;
      codDueTotal += codDue;
    } else {
      paidOnlineTotal += total;
    }
  });

  let csvContent = "";
  csvContent += "GRM GARMENTS - WHATSAPP SALES & ORDER DASHBOARD REPORT\r\n";
  csvContent += "Generated On:,\"" + new Date().toLocaleString() + "\"\r\n";
  if (fromVal || toVal) {
    csvContent += "Date Range Filter:,\"" + (fromVal ? ("From " + fromVal) : "Up to") + (toVal ? (" To " + toVal) : "") + "\"\r\n";
  }
  csvContent += "\r\n";

  csvContent += "EXECUTIVE REVENUE SUMMARY\r\n";
  csvContent += "Total Orders Booked," + orders.length + "\r\n";
  csvContent += "Overall Gross Revenue (INR),Rs " + overallRevenue.toFixed(2) + "\r\n";
  csvContent += "Paid Online Collected (INR),Rs " + paidOnlineTotal.toFixed(2) + "\r\n";
  csvContent += "COD Balance Due (INR),Rs " + codDueTotal.toFixed(2) + "\r\n";
  csvContent += "Average Order Value (AOV),Rs " + (orders.length > 0 ? (overallRevenue / orders.length).toFixed(2) : '0.00') + "\r\n\r\n";

  // Note: ORDER FULFILLMENT PIPELINE STATUS removed from dashboard export as requested

  csvContent += "STAFF NAME WISE TOTAL ORDER COUNT & PERFORMANCE\r\n";
  csvContent += "Staff Member,Role / Department,Orders Booked,Total Revenue (INR),Placed,Packed,Shipped,Out for Delivery,Delivered,Share of Orders (%)\r\n";

  const staffMembers = [...(CRM_STATE?.staffList || [])];
  if (!staffMembers.some(s => s.id === 'admin' || s.name === 'Super Admin')) {
    staffMembers.push({ id: 'admin', name: 'Super Admin', role: 'Admin Manager (Full System)' });
  }

  staffMembers.forEach(staff => {
    const sOrders = orders.filter(o => {
      const matchId = o.staffId && (o.staffId === staff.id || o.staff_id === staff.id);
      const matchName = (o.staffName && o.staffName.toLowerCase().includes(staff.name.toLowerCase())) ||
        (o.staff_name && o.staff_name.toLowerCase().includes(staff.name.toLowerCase())) ||
        (o.createdBy && o.createdBy.toLowerCase().includes(staff.name.toLowerCase())) ||
        (o.created_by && o.created_by.toLowerCase().includes(staff.name.toLowerCase()));
      return matchId || matchName;
    });
    const count = sOrders.length;
    const rev = sOrders.reduce((sum, o) => sum + (parseFloat(o.grandTotal || o.grand_total) || 0), 0);
    const p = sOrders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'PLACED').length;
    const pk = sOrders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'PACKED').length;
    const sh = sOrders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'SHIPPED').length;
    const od = sOrders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'OUT_FOR_DELIVERY').length;
    const del = sOrders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'DELIVERED').length;
    const share = orders.length > 0 ? Math.round((count / orders.length) * 100) : 0;

    csvContent += "\"" + (staff.name || '').replace(/"/g, '""') + "\",\"" + (staff.role || 'Sales Specialist').replace(/"/g, '""') + "\"," + count + "," + rev.toFixed(2) + "," + p + "," + pk + "," + sh + "," + od + "," + del + "," + share + "%\r\n";
  });

  const dateSuffix = (fromVal && toVal) ? ("_" + fromVal + "_to_" + toVal) : ("_" + new Date().toISOString().split('T')[0]);
  const filename = "GRM_WhatsApp_Sales_Dashboard_Report" + dateSuffix + ".csv";
  downloadOrdersCSVBlob(filename, csvContent);
  if (typeof showToast === 'function') {
    showToast('Report Downloaded', orders.length + ' orders exported' + (fromVal || toVal ? ' for chosen date range.' : '.'), 'download', 'emerald');
  }
}
window.downloadOrdersDashboardReport = downloadOrdersDashboardReport;

